#include <cmath>
#include <string>

struct Vector2 { float x, y; };

bool inView(Vector2 pos, Vector2 facing, Vector2 target, float range, float halfAngleDegrees)
{
    const float dx{ target.x - pos.x }, dy{ target.y - pos.y };
    const float dist{ std::sqrt(dx * dx + dy * dy) };
    if (dist > range) return false;
    if (dist == 0) return true;
    const float cosAngle{ (dx * facing.x + dy * facing.y) / dist };
    return cosAngle >= std::cos(halfAngleDegrees * 3.14159265f / 180.0f) - 1e-6f;
}

enum class State { Patrol, Alert, Chase, Attack, Return, Hurt };
struct Senses { bool seesPlayer; float distance; bool attackFinished; bool atPatrolRoute; bool wasHit; };
struct Brain { State state{ State::Patrol }; float timer{ 0 }; float unseen{ 0 }; };

namespace
{
    void enter(Brain& b, State s) { b.state = s; b.timer = 0; b.unseen = 0; }
}

void think(Brain& b, const Senses& s, float dt)
{
    b.timer += dt;
    if (s.wasHit) { enter(b, State::Hurt); return; }
    switch (b.state)
    {
    case State::Patrol: if (s.seesPlayer) enter(b, State::Alert); break;
    case State::Alert: if (b.timer >= 0.3f) enter(b, State::Chase); break;
    case State::Chase:
        if (s.distance < 24) { enter(b, State::Attack); break; }
        b.unseen = s.seesPlayer ? 0 : b.unseen + dt;
        if (b.unseen >= 3) enter(b, State::Return);
        break;
    case State::Attack: if (s.attackFinished) enter(b, State::Chase); break;
    case State::Return:
        if (s.seesPlayer) enter(b, State::Chase);
        else if (s.atPatrolRoute) enter(b, State::Patrol);
        break;
    case State::Hurt: if (b.timer >= 0.3f) enter(b, State::Chase); break;
    }
}

std::string name(State s)
{
    switch (s)
    {
    case State::Patrol: return "Patrol";
    case State::Alert: return "Alert";
    case State::Chase: return "Chase";
    case State::Attack: return "Attack";
    case State::Return: return "Return";
    case State::Hurt: return "Hurt";
    }
    return "";
}

unitTests:
const Senses nothing{ false, 500, false, false, false };
Senses seeing(float d) { return { true, d, false, false, false }; }
TEST("field of view") {
    CHECK(inView({ 0, 0 }, { 1, 0 }, { 100, 0 }, 100, 45)); CHECK(!inView({ 0, 0 }, { 1, 0 }, { 101, 0 }, 100, 45));
    CHECK(inView({ 0, 0 }, { 1, 0 }, { 50, 49 }, 100, 45)); CHECK(!inView({ 0, 0 }, { 1, 0 }, { 50, 51 }, 100, 45));
    CHECK(!inView({ 0, 0 }, { 1, 0 }, { -10, 0 }, 100, 45)); CHECK(inView({ 5, 5 }, { 0, 1 }, { 5, 5 }, 10, 10));
}
TEST("spotting and reacting") {
    Brain b; think(b, seeing(200), 0.016f); CHECK_EQ(name(b.state), std::string("Alert"));
    think(b, seeing(200), 0.15f); CHECK_EQ(name(b.state), std::string("Alert"));
    think(b, seeing(200), 0.2f); CHECK_EQ(name(b.state), std::string("Chase"));
}
TEST("chase, attack, chase") {
    Brain b; b.state = State::Chase; think(b, seeing(20), 0.016f); CHECK_EQ(name(b.state), std::string("Attack"));
    think(b, seeing(20), 0.016f); CHECK_EQ(name(b.state), std::string("Attack"));
    think(b, { true, 20, true, false, false }, 0.016f); CHECK_EQ(name(b.state), std::string("Chase"));
}
TEST("losing the player") {
    Brain b; b.state = State::Chase;
    for (int i = 0; i < 20; ++i) think(b, nothing, 0.1f); think(b, seeing(300), 0.1f); CHECK_NEAR(b.unseen, 0.0, 1e-6);
    for (int i = 0; i < 29; ++i) think(b, nothing, 0.1f); CHECK_EQ(name(b.state), std::string("Chase"));
    think(b, nothing, 0.11f); CHECK_EQ(name(b.state), std::string("Return"));
    think(b, { false, 500, false, true, false }, 0.1f); CHECK_EQ(name(b.state), std::string("Patrol"));
}
TEST("hits interrupt everything") {
    Brain b; b.state = State::Attack; b.timer = 5; think(b, { true, 10, false, false, true }, 0.1f); CHECK_EQ(name(b.state), std::string("Hurt")); CHECK_NEAR(b.timer, 0.0, 1e-6);
    think(b, nothing, 0.2f); think(b, { false, 500, false, false, true }, 0.2f); CHECK_EQ(name(b.state), std::string("Hurt"));
    think(b, nothing, 0.2f); CHECK_EQ(name(b.state), std::string("Hurt")); think(b, nothing, 0.2f); CHECK_EQ(name(b.state), std::string("Chase"));
}

